BEGIN TRANSACTION;
CREATE TABLE community_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT,
    reviewer_name TEXT NOT NULL,
    reviewer_title TEXT NOT NULL,
    reviewer_organization TEXT NOT NULL,
    rating INTEGER DEFAULT 5,
    review_text TEXT NOT NULL,
    verified_badge TEXT DEFAULT 'VERIFIED_COMMUNITY_ENGINEER',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(project_id) REFERENCES community_verified_projects(project_id)
);
CREATE TABLE community_stats (
    stat_key TEXT PRIMARY KEY,
    stat_value TEXT NOT NULL,
    description TEXT
);
CREATE TABLE community_verified_projects (
    project_id TEXT PRIMARY KEY,
    app_name TEXT NOT NULL,
    tagline TEXT,
    preset TEXT,
    repo_url TEXT NOT NULL,
    commit_hash TEXT NOT NULL,
    headmaster_score INTEGER DEFAULT 100,
    status TEXT DEFAULT 'COMMUNITY_VERIFIED',
    community_stamp_id TEXT NOT NULL,
    crypto_stamp_hash TEXT NOT NULL,
    native_resolution TEXT DEFAULT '1080x2400 Pixel 6 (API 34)',
    clean_architecture INTEGER DEFAULT 1,
    zero_emojis INTEGER DEFAULT 1,
    community_rating REAL DEFAULT 4.96,
    community_reviews_count INTEGER DEFAULT 18,
    verified_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sql_audit_log (
    audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id TEXT NOT NULL,
    audit_type TEXT NOT NULL,
    auditor TEXT NOT NULL,
    verdict TEXT NOT NULL,
    details TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_proj_status ON community_verified_projects(status);
CREATE INDEX idx_rev_proj ON community_reviews(project_id);
DELETE FROM "sqlite_sequence";
COMMIT;
